-- ######## setup/00_prelude.sql ########
-- =============================================
-- 00 — Businesses + user profiles (needed by everything else)
-- The app is multi-business: every login belongs to one business (user_profiles.business_id).
-- These tables existed in the old live database but were never in the repo's SQL files.
-- =============================================

CREATE TABLE IF NOT EXISTS public.businesses (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  business_name TEXT NOT NULL DEFAULT '',
  owner_email TEXT,
  status TEXT NOT NULL DEFAULT 'active',
  subscription_amount NUMERIC(12, 2) NOT NULL DEFAULT 0,
  payment_status TEXT NOT NULL DEFAULT 'unpaid',
  payment_due_date DATE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.user_profiles (
  id UUID PRIMARY KEY REFERENCES auth.users (id) ON DELETE CASCADE,
  full_name TEXT NOT NULL DEFAULT '',
  email TEXT NOT NULL,
  role TEXT NOT NULL DEFAULT 'staff',
  business_id UUID REFERENCES public.businesses (id) ON DELETE SET NULL,
  phone TEXT,
  trial_ends_at TIMESTAMPTZ,
  subscription_ends_at TIMESTAMPTZ,
  is_platform_admin BOOLEAN NOT NULL DEFAULT false,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- The code accepts 'super_admin' as well as admin/staff.
ALTER TABLE public.user_profiles DROP CONSTRAINT IF EXISTS user_profiles_role_check;
ALTER TABLE public.user_profiles
  ADD CONSTRAINT user_profiles_role_check CHECK (role IN ('admin', 'staff', 'super_admin'));

CREATE INDEX IF NOT EXISTS idx_user_profiles_business ON public.user_profiles (business_id);

/** The signed-in user's business (NULL for the service role / no profile). */
CREATE OR REPLACE FUNCTION public.current_business_id()
RETURNS UUID
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT business_id FROM public.user_profiles WHERE id = auth.uid();
$$;

GRANT EXECUTE ON FUNCTION public.current_business_id() TO anon, authenticated, service_role;

ALTER TABLE public.businesses ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS businesses_select_own ON public.businesses;
CREATE POLICY businesses_select_own ON public.businesses
  FOR SELECT TO authenticated
  USING (id = public.current_business_id());

GRANT SELECT ON public.businesses TO authenticated;
GRANT ALL ON public.businesses TO service_role;


-- ######## supabase.schema.sql ########
-- =============================================
-- Step 1: Tables, indexes, RLS, grants
-- Supabase Dashboard → SQL Editor → Run this file first
-- =============================================

CREATE TABLE IF NOT EXISTS public.products (
  id BIGSERIAL PRIMARY KEY,
  name TEXT NOT NULL,
  category TEXT NOT NULL,
  price NUMERIC(12, 2) NOT NULL DEFAULT 0,
  retail_price NUMERIC(12, 2) NOT NULL DEFAULT 0,
  cost_price NUMERIC(12, 2) NOT NULL DEFAULT 0,
  stock_quantity INTEGER NOT NULL DEFAULT 0,
  supplier TEXT NOT NULL DEFAULT '',
  unit_type TEXT NOT NULL DEFAULT 'Piece' CHECK (unit_type IN ('ML', 'L', 'KG', 'Gram', 'Piece', 'Box', 'Dozen')),
  unit_size NUMERIC(12, 2) NOT NULL DEFAULT 1,
  sku TEXT,
  description TEXT NOT NULL DEFAULT '',
  fragrance TEXT NOT NULL DEFAULT 'Unscented',
  hsn_sac TEXT NOT NULL DEFAULT '',
  is_active BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_products_sku_unique
  ON public.products (sku)
  WHERE sku IS NOT NULL AND sku <> '';

COMMENT ON COLUMN public.products.price IS 'Wholesale selling price (B2B)';
COMMENT ON COLUMN public.products.retail_price IS 'Retail / consumer selling price (MRP)';

CREATE TABLE IF NOT EXISTS public.parties (
  id BIGSERIAL PRIMARY KEY,
  name TEXT NOT NULL,
  type TEXT NOT NULL CHECK (type IN ('retailer', 'wholesaler', 'manufacturer')),
  contact TEXT DEFAULT '',
  address TEXT DEFAULT '',
  gst_number TEXT DEFAULT '',
  balance NUMERIC(12, 2) NOT NULL DEFAULT 0,
  is_active BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.purchases (
  id BIGSERIAL PRIMARY KEY,
  party_id BIGINT NOT NULL REFERENCES public.parties (id),
  purchase_date DATE NOT NULL,
  subtotal NUMERIC(12, 2) NOT NULL DEFAULT 0,
  gst_percent NUMERIC(5, 2) NOT NULL DEFAULT 18,
  gst_amount NUMERIC(12, 2) NOT NULL DEFAULT 0,
  total_amount NUMERIC(12, 2) NOT NULL DEFAULT 0,
  notes TEXT DEFAULT '',
  payment_due_date DATE,
  amount_paid NUMERIC(12, 2) NOT NULL DEFAULT 0 CHECK (amount_paid >= 0),
  payment_status TEXT NOT NULL DEFAULT 'paid' CHECK (payment_status IN ('paid', 'pending', 'partial')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.purchase_items (
  id BIGSERIAL PRIMARY KEY,
  purchase_id BIGINT NOT NULL REFERENCES public.purchases (id) ON DELETE CASCADE,
  product_id BIGINT NOT NULL REFERENCES public.products (id),
  quantity INTEGER NOT NULL,
  rate NUMERIC(12, 2) NOT NULL,
  amount NUMERIC(12, 2) NOT NULL
);

CREATE TABLE IF NOT EXISTS public.sales (
  id BIGSERIAL PRIMARY KEY,
  party_id BIGINT NOT NULL REFERENCES public.parties (id),
  invoice_number TEXT NOT NULL UNIQUE,
  invoice_date DATE NOT NULL,
  subtotal NUMERIC(12, 2) NOT NULL DEFAULT 0,
  gst_percent NUMERIC(5, 2) NOT NULL DEFAULT 18,
  gst_amount NUMERIC(12, 2) NOT NULL DEFAULT 0,
  total_amount NUMERIC(12, 2) NOT NULL DEFAULT 0,
  payment_bank_name TEXT,
  payment_account_number TEXT,
  payment_ifsc TEXT,
  payment_upi TEXT,
  payment_terms TEXT,
  payment_due_date DATE,
  amount_paid NUMERIC(12, 2) NOT NULL DEFAULT 0 CHECK (amount_paid >= 0),
  payment_status TEXT NOT NULL DEFAULT 'paid' CHECK (payment_status IN ('paid', 'pending', 'partial')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  is_deleted BOOLEAN NOT NULL DEFAULT false,
  deleted_at TIMESTAMPTZ,
  deleted_by UUID REFERENCES public.user_profiles (id),
  delete_reason TEXT
);

CREATE TABLE IF NOT EXISTS public.sale_items (
  id BIGSERIAL PRIMARY KEY,
  sale_id BIGINT NOT NULL REFERENCES public.sales (id) ON DELETE CASCADE,
  product_id BIGINT NOT NULL REFERENCES public.products (id),
  quantity INTEGER NOT NULL,
  rate NUMERIC(12, 2) NOT NULL,
  amount NUMERIC(12, 2) NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_purchases_party_id ON public.purchases (party_id);
CREATE INDEX IF NOT EXISTS idx_purchases_date ON public.purchases (purchase_date);
CREATE INDEX IF NOT EXISTS idx_sales_party_id ON public.sales (party_id);
CREATE INDEX IF NOT EXISTS idx_sales_invoice_date ON public.sales (invoice_date);
CREATE INDEX IF NOT EXISTS idx_purchase_items_product ON public.purchase_items (product_id);
CREATE INDEX IF NOT EXISTS idx_sale_items_product ON public.sale_items (product_id);

CREATE TABLE IF NOT EXISTS public.expenses (
  id BIGSERIAL PRIMARY KEY,
  title TEXT NOT NULL,
  category TEXT NOT NULL CHECK (
    category IN (
      'Rent',
      'Salary',
      'Labour / Wages',
      'Electricity',
      'Water',
      'Transport',
      'Petrol / Fuel',
      'Food',
      'Chai / Tea',
      'Packaging',
      'Courier / Shipping',
      'Mobile & Internet',
      'Office Supplies',
      'Maintenance',
      'Repairs',
      'Marketing',
      'Cleaning Supplies',
      'Other'
    )
  ),
  amount NUMERIC(12, 2) NOT NULL DEFAULT 0 CHECK (amount >= 0),
  expense_date DATE NOT NULL,
  payment_method TEXT NOT NULL CHECK (payment_method IN ('Cash', 'Bank', 'UPI')),
  notes TEXT NOT NULL DEFAULT '',
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_expenses_date ON public.expenses (expense_date);
CREATE INDEX IF NOT EXISTS idx_expenses_category ON public.expenses (category);

CREATE TABLE IF NOT EXISTS public.employees (
  id BIGSERIAL PRIMARY KEY,
  name TEXT NOT NULL,
  role TEXT NOT NULL CHECK (
    role IN ('Salesman', 'Manager', 'Accountant', 'Delivery Boy')
  ),
  contact TEXT NOT NULL DEFAULT '',
  salary NUMERIC(12, 2) NOT NULL DEFAULT 0 CHECK (salary >= 0),
  joining_date DATE NOT NULL,
  status TEXT NOT NULL DEFAULT 'Active' CHECK (status IN ('Active', 'Inactive')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_employees_status ON public.employees (status);

CREATE TABLE IF NOT EXISTS public.salary_payments (
  id BIGSERIAL PRIMARY KEY,
  employee_id BIGINT NOT NULL REFERENCES public.employees (id) ON DELETE CASCADE,
  month TEXT NOT NULL CHECK (month ~ '^\d{4}-\d{2}$'),
  amount NUMERIC(12, 2) NOT NULL DEFAULT 0 CHECK (amount >= 0),
  paid_date DATE NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (employee_id, month)
);

CREATE INDEX IF NOT EXISTS idx_salary_payments_month ON public.salary_payments (month);

ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.parties ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.purchases ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.purchase_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.sales ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.sale_items ENABLE ROW LEVEL SECURITY;
