-- ######## supabase.migration.stock_restore_on_delete.sql ########
-- =============================================
-- Stock restore on sale/purchase delete + safer updates
-- Run in Supabase SQL Editor after sale_atomic_payment migration
-- =============================================

-- Returns { "restored": [...], "skipped": [...] }
-- Older versions returned VOID; Postgres cannot change a return type in place.
DROP FUNCTION IF EXISTS public.delete_sale(BIGINT);
DROP FUNCTION IF EXISTS public.delete_purchase(BIGINT);

CREATE OR REPLACE FUNCTION public.delete_sale(p_sale_id BIGINT)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_party_id BIGINT;
  v_total NUMERIC(12, 2);
  v_item RECORD;
  v_restored JSONB := '[]'::JSONB;
  v_skipped JSONB := '[]'::JSONB;
BEGIN
  SELECT party_id, total_amount INTO v_party_id, v_total
  FROM public.sales
  WHERE id = p_sale_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Sale not found';
  END IF;

  FOR v_item IN
    SELECT
      si.product_id,
      si.quantity,
      p.name AS product_name
    FROM public.sale_items si
    LEFT JOIN public.products p ON p.id = si.product_id
    WHERE si.sale_id = p_sale_id
  LOOP
    IF v_item.product_name IS NULL THEN
      v_skipped := v_skipped || jsonb_build_object(
        'product_id', v_item.product_id,
        'quantity', v_item.quantity,
        'reason', 'product_not_found'
      );
      CONTINUE;
    END IF;

    UPDATE public.products
    SET stock_quantity = stock_quantity + v_item.quantity
    WHERE id = v_item.product_id;

    v_restored := v_restored || jsonb_build_object(
      'product_id', v_item.product_id,
      'product_name', v_item.product_name,
      'quantity', v_item.quantity
    );
  END LOOP;

  UPDATE public.parties
  SET balance = balance - v_total
  WHERE id = v_party_id;

  DELETE FROM public.sales WHERE id = p_sale_id;

  RETURN jsonb_build_object('restored', v_restored, 'skipped', v_skipped);
END;
$$;

CREATE OR REPLACE FUNCTION public.delete_purchase(p_purchase_id BIGINT)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_party_id BIGINT;
  v_total NUMERIC(12, 2);
  v_item RECORD;
  v_reversed JSONB := '[]'::JSONB;
  v_skipped JSONB := '[]'::JSONB;
BEGIN
  SELECT party_id, total_amount INTO v_party_id, v_total
  FROM public.purchases
  WHERE id = p_purchase_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Purchase not found';
  END IF;

  FOR v_item IN
    SELECT
      pi.product_id,
      pi.quantity,
      p.name AS product_name
    FROM public.purchase_items pi
    LEFT JOIN public.products p ON p.id = pi.product_id
    WHERE pi.purchase_id = p_purchase_id
  LOOP
    IF v_item.product_name IS NULL THEN
      v_skipped := v_skipped || jsonb_build_object(
        'product_id', v_item.product_id,
        'quantity', v_item.quantity,
        'reason', 'product_not_found'
      );
      CONTINUE;
    END IF;

    UPDATE public.products
    SET stock_quantity = stock_quantity - v_item.quantity
    WHERE id = v_item.product_id;

    v_reversed := v_reversed || jsonb_build_object(
      'product_id', v_item.product_id,
      'product_name', v_item.product_name,
      'quantity', v_item.quantity
    );
  END LOOP;

  UPDATE public.parties
  SET balance = balance + v_total
  WHERE id = v_party_id;

  DELETE FROM public.purchases WHERE id = p_purchase_id;

  RETURN jsonb_build_object('reversed', v_reversed, 'skipped', v_skipped);
END;
$$;

