    v_rate := (v_item ->> 'rate')::NUMERIC;
    v_amount := v_qty * v_rate;

    INSERT INTO sale_items (sale_id, product_id, quantity, rate, amount)
    VALUES (p_sale_id, v_product_id, v_qty, v_rate, v_amount);

    UPDATE products
    SET stock_quantity = stock_quantity - v_qty
    WHERE id = v_product_id;
  END LOOP;

  UPDATE parties
  SET balance = balance + v_total
  WHERE id = p_party_id;

  PERFORM public.apply_sale_payment_from_json(p_sale_id, p_payment);

  RETURN p_sale_id;
END;
$update_sale$;

GRANT EXECUTE ON FUNCTION public.restore_sale_stock_for_delete(BIGINT) TO anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.soft_delete_sale(BIGINT, UUID, TEXT) TO anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.hard_delete_sale(BIGINT) TO anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.delete_sale(BIGINT) TO anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.update_sale(BIGINT, BIGINT, DATE, NUMERIC, JSONB, JSONB) TO anon, authenticated, service_role;



-- ######## supabase.migration.delete_party_cascade.sql ########
-- =============================================
-- Cascade-delete a party with all linked sales/purchases
-- Run in Supabase SQL Editor after sales_soft_delete migration
-- Safe to re-run (CREATE OR REPLACE)
-- =============================================
-- Relations handled:
--   sales.party_id → parties.id
--   sale_items.sale_id → sales.id (ON DELETE CASCADE)
--   purchases.party_id → parties.id
--   purchase_items.purchase_id → purchases.id (ON DELETE CASCADE)
-- Payment fields live on sales row (no separate payments table).
-- =============================================

CREATE OR REPLACE FUNCTION public.delete_party_cascade(p_party_id BIGINT)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_party_name TEXT;
  v_sale RECORD;
  v_purchase RECORD;
  v_sales_deleted INT := 0;
  v_purchases_deleted INT := 0;
BEGIN
  SELECT name INTO v_party_name
  FROM public.parties
  WHERE id = p_party_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Party not found';
  END IF;

  -- Active sales: restore stock + reverse balance, then hard-delete (sale_items cascade).
  -- Soft-deleted sales: stock/balance already restored — just remove the row.
  FOR v_sale IN
    SELECT id, COALESCE(is_deleted, false) AS is_deleted
    FROM public.sales
    WHERE party_id = p_party_id
    ORDER BY id
  LOOP
    IF v_sale.is_deleted THEN
      DELETE FROM public.sales WHERE id = v_sale.id;
    ELSE
      PERFORM public.hard_delete_sale(v_sale.id);
    END IF;
    v_sales_deleted := v_sales_deleted + 1;
  END LOOP;

  -- Purchases: reverse stock additions + party balance, then delete (purchase_items cascade).
  FOR v_purchase IN
    SELECT id
    FROM public.purchases
    WHERE party_id = p_party_id
    ORDER BY id
  LOOP
    PERFORM public.delete_purchase(v_purchase.id);
    v_purchases_deleted := v_purchases_deleted + 1;
  END LOOP;

  DELETE FROM public.parties WHERE id = p_party_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Party not found';
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'party_id', p_party_id,
    'party_name', v_party_name,
    'sales_deleted', v_sales_deleted,
    'purchases_deleted', v_purchases_deleted
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.delete_party_cascade(BIGINT) TO anon, authenticated, service_role;



-- ######## supabase.migration.delete_product_smart.sql ########
-- Smart product delete:
--   - Blocked if any sale_items reference the product (status: blocked_has_sales)
--   - If only purchase_items: remove those links (and empty/sole-product purchases), then delete product
--   - If no links: delete product
-- Safe to re-run (CREATE OR REPLACE)
-- Run in Supabase SQL Editor, then NOTIFY reloads PostgREST.

CREATE OR REPLACE FUNCTION public.delete_product_smart(p_product_id BIGINT)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_product_name TEXT;
  v_sale_count INT := 0;
  v_purchase_item_count INT := 0;
  v_purchases_removed INT := 0;
  v_purchase RECORD;
  v_line_amount NUMERIC(12, 2);
  v_line_qty INT;
  v_has_delete_purchase BOOLEAN;
BEGIN
  SELECT name INTO v_product_name
  FROM public.products
  WHERE id = p_product_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'status', 'not_found',
      'product_id', p_product_id
    );
  END IF;

  SELECT COUNT(*)::INT INTO v_sale_count
  FROM public.sale_items
  WHERE product_id = p_product_id;

  IF v_sale_count > 0 THEN
    RETURN jsonb_build_object(
      'status', 'blocked_has_sales',
      'product_id', p_product_id,
      'product_name', v_product_name,
      'sale_items', v_sale_count
    );
  END IF;

  SELECT COUNT(*)::INT INTO v_purchase_item_count
  FROM public.purchase_items
  WHERE product_id = p_product_id;

  v_has_delete_purchase := to_regprocedure('public.delete_purchase(bigint)') IS NOT NULL;

  -- Purchases that only contain this product → full purchase delete (stock + party balance)
  FOR v_purchase IN
    SELECT p.id, p.party_id, p.total_amount
    FROM public.purchases p
    WHERE EXISTS (
      SELECT 1 FROM public.purchase_items pi
      WHERE pi.purchase_id = p.id AND pi.product_id = p_product_id
    )
    AND NOT EXISTS (
      SELECT 1 FROM public.purchase_items pi
      WHERE pi.purchase_id = p.id AND pi.product_id <> p_product_id
    )
    ORDER BY p.id
  LOOP
    IF v_has_delete_purchase THEN
      PERFORM public.delete_purchase(v_purchase.id);
    ELSE
      UPDATE public.parties
      SET balance = balance + COALESCE(v_purchase.total_amount, 0)
      WHERE id = v_purchase.party_id;

      DELETE FROM public.purchases WHERE id = v_purchase.id;
    END IF;
    v_purchases_removed := v_purchases_removed + 1;
  END LOOP;

  -- Remaining mixed purchases: drop only this product's lines and adjust totals/balance
  FOR v_purchase IN
    SELECT
      p.id,
      p.party_id,
      COALESCE(SUM(pi.amount), 0)::NUMERIC(12, 2) AS line_amount,
      COALESCE(SUM(pi.quantity), 0)::INT AS line_qty
    FROM public.purchases p
    INNER JOIN public.purchase_items pi
      ON pi.purchase_id = p.id AND pi.product_id = p_product_id
    GROUP BY p.id, p.party_id
    ORDER BY p.id
  LOOP
    v_line_amount := v_purchase.line_amount;
    v_line_qty := v_purchase.line_qty;

    DELETE FROM public.purchase_items
    WHERE purchase_id = v_purchase.id
      AND product_id = p_product_id;

    UPDATE public.purchases
    SET
      subtotal = GREATEST(0, COALESCE(subtotal, 0) - v_line_amount),
      total_amount = GREATEST(0, COALESCE(total_amount, 0) - v_line_amount)
    WHERE id = v_purchase.id;

    UPDATE public.parties
    SET balance = balance + v_line_amount
    WHERE id = v_purchase.party_id;

    -- Product still exists at this point; reverse stock from those purchase lines
    UPDATE public.products
    SET stock_quantity = stock_quantity - v_line_qty
    WHERE id = p_product_id;
  END LOOP;

  DELETE FROM public.products WHERE id = p_product_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'status', 'not_found',
      'product_id', p_product_id
    );
  END IF;

  RETURN jsonb_build_object(
    'status', 'deleted',
    'product_id', p_product_id,
    'product_name', v_product_name,
    'purchase_items_removed', v_purchase_item_count,
    'purchases_removed', v_purchases_removed
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.delete_product_smart(BIGINT) TO anon, authenticated, service_role;



-- ######## supabase.migration.next_invoice_number.sql ########
-- Atomic next invoice number (includes soft-deleted rows).
-- Run once in Supabase SQL Editor.

CREATE OR REPLACE FUNCTION public.next_sales_invoice_number(p_year INTEGER DEFAULT NULL)
RETURNS TEXT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_year INTEGER := COALESCE(p_year, EXTRACT(YEAR FROM NOW())::INTEGER);
  v_prefix TEXT := 'INV-' || v_year::TEXT || '-';
  v_max INTEGER := 0;
  v_suffix TEXT;
  v_n INTEGER;
  r RECORD;
BEGIN
  -- Serialize allocations within a transaction
  PERFORM pg_advisory_xact_lock(87231421);

  FOR r IN
    SELECT invoice_number
    FROM public.sales
    WHERE invoice_number LIKE v_prefix || '%'
  LOOP
    v_suffix := split_part(r.invoice_number, '-', 3);
    BEGIN
      v_n := v_suffix::INTEGER;
      IF v_n > v_max THEN
        v_max := v_n;
      END IF;
    EXCEPTION WHEN others THEN
      NULL;
    END;
  END LOOP;

  RETURN v_prefix || lpad((v_max + 1)::TEXT, 3, '0');
END;
$$;

GRANT EXECUTE ON FUNCTION public.next_sales_invoice_number(INTEGER) TO anon, authenticated, service_role;



-- ######## supabase.rebuild.pre_bookings.sql ########
-- Pre-bookings clean rebuild. Run once in Supabase SQL Editor (entire file).
-- Drops leftover single-product header columns (product_id, quantity, …)
-- and recreates header + line items + atomic create_pre_booking().

DROP FUNCTION IF EXISTS public.create_pre_booking(TEXT, BIGINT, DATE, TEXT, JSONB);

DROP TABLE IF EXISTS public.pre_booking_items CASCADE;
DROP TABLE IF EXISTS public.pre_bookings CASCADE;

CREATE TABLE public.pre_bookings (
  id BIGSERIAL PRIMARY KEY,
  business_id TEXT NOT NULL,
  party_id BIGINT NOT NULL REFERENCES public.parties (id) ON DELETE CASCADE,
  delivery_date DATE NOT NULL,
  notes TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'upcoming' CHECK (status IN ('upcoming', 'delivered', 'cancelled')),
  subtotal NUMERIC(12, 2) NOT NULL DEFAULT 0,
  gst_total NUMERIC(12, 2) NOT NULL DEFAULT 0,
  total_amount NUMERIC(12, 2) NOT NULL DEFAULT 0 CHECK (total_amount >= 0),
  converted_invoice_id BIGINT REFERENCES public.sales (id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

COMMENT ON TABLE public.pre_bookings IS
  'Future-order reminders (header). Products live only in pre_booking_items.';

CREATE INDEX pre_bookings_business_id_idx ON public.pre_bookings (business_id);
CREATE INDEX pre_bookings_delivery_date_idx ON public.pre_bookings (delivery_date);
CREATE INDEX pre_bookings_status_idx ON public.pre_bookings (status);
CREATE INDEX pre_bookings_party_id_idx ON public.pre_bookings (party_id);
CREATE INDEX pre_bookings_converted_invoice_id_idx ON public.pre_bookings (converted_invoice_id);

ALTER TABLE public.pre_bookings ENABLE ROW LEVEL SECURITY;

CREATE POLICY pre_bookings_authenticated_all
  ON public.pre_bookings
  FOR ALL
  TO authenticated
  USING (true)
  WITH CHECK (true);

GRANT SELECT, INSERT, UPDATE, DELETE ON public.pre_bookings TO authenticated;
GRANT ALL ON public.pre_bookings TO service_role;
GRANT USAGE, SELECT ON SEQUENCE public.pre_bookings_id_seq TO authenticated;
GRANT ALL ON SEQUENCE public.pre_bookings_id_seq TO service_role;

CREATE TABLE public.pre_booking_items (
  id BIGSERIAL PRIMARY KEY,
  pre_booking_id BIGINT NOT NULL REFERENCES public.pre_bookings (id) ON DELETE CASCADE,
  product_id BIGINT NOT NULL REFERENCES public.products (id) ON DELETE RESTRICT,
  quantity NUMERIC(12, 2) NOT NULL CHECK (quantity > 0),
  rate NUMERIC(12, 2) NOT NULL DEFAULT 0 CHECK (rate >= 0),
  gst_percent NUMERIC(5, 2) NOT NULL DEFAULT 0 CHECK (gst_percent >= 0),
  gst_amount NUMERIC(12, 2) NOT NULL DEFAULT 0 CHECK (gst_amount >= 0),
  amount NUMERIC(12, 2) NOT NULL DEFAULT 0 CHECK (amount >= 0),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

COMMENT ON TABLE public.pre_booking_items IS
  'Line products for a pre-booking. amount is the line total including GST.';
COMMENT ON COLUMN public.pre_bookings.subtotal IS
  'Sum of rate × qty across lines, before GST.';
COMMENT ON COLUMN public.pre_bookings.gst_total IS
  'Sum of line gst_amount.';
COMMENT ON COLUMN public.pre_bookings.total_amount IS
  'Grand total including GST (subtotal + gst_total).';
COMMENT ON COLUMN public.pre_booking_items.amount IS
  'Line total including GST (rate × qty + gst_amount).';

CREATE INDEX pre_booking_items_booking_idx ON public.pre_booking_items (pre_booking_id);
CREATE INDEX pre_booking_items_product_idx ON public.pre_booking_items (product_id);

ALTER TABLE public.pre_booking_items ENABLE ROW LEVEL SECURITY;

CREATE POLICY pre_booking_items_authenticated_all
  ON public.pre_booking_items
  FOR ALL
  TO authenticated
  USING (true)
  WITH CHECK (true);

GRANT SELECT, INSERT, UPDATE, DELETE ON public.pre_booking_items TO authenticated;
GRANT ALL ON public.pre_booking_items TO service_role;
GRANT USAGE, SELECT ON SEQUENCE public.pre_booking_items_id_seq TO authenticated;
GRANT ALL ON SEQUENCE public.pre_booking_items_id_seq TO service_role;

CREATE OR REPLACE FUNCTION public.create_pre_booking(
  p_business_id TEXT,
  p_party_id BIGINT,
  p_delivery_date DATE,
  p_notes TEXT,
  p_items JSONB
)
RETURNS BIGINT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_id BIGINT;
  v_item JSONB;
  v_product_id BIGINT;
  v_qty NUMERIC(12, 2);
  v_rate NUMERIC(12, 2);
  v_gst_percent NUMERIC(5, 2);
  v_taxable NUMERIC(12, 2);
  v_gst_amount NUMERIC(12, 2);
  v_amount NUMERIC(12, 2);
  v_subtotal NUMERIC(12, 2) := 0;
  v_gst_total NUMERIC(12, 2) := 0;
  v_total NUMERIC(12, 2) := 0;
BEGIN
  IF p_business_id IS NULL OR length(trim(p_business_id)) = 0 THEN
    RAISE EXCEPTION 'Business is required';
  END IF;
  IF p_party_id IS NULL OR p_party_id <= 0 THEN
    RAISE EXCEPTION 'Party is required';
  END IF;
  IF p_delivery_date IS NULL THEN
    RAISE EXCEPTION 'Delivery date is required';
  END IF;
  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'Add at least one product';
  END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items)
  LOOP
    v_product_id := NULLIF(v_item ->> 'product_id', '')::BIGINT;
    v_qty := COALESCE(NULLIF(v_item ->> 'quantity', '')::NUMERIC, 0);
    v_rate := COALESCE(NULLIF(v_item ->> 'rate', '')::NUMERIC, 0);
    IF v_item ->> 'gst_percent' IS NULL OR v_item ->> 'gst_percent' = '' THEN
      v_gst_percent := 18;
    ELSE
      v_gst_percent := COALESCE((v_item ->> 'gst_percent')::NUMERIC, 0);
    END IF;

    IF v_product_id IS NULL OR v_product_id <= 0 THEN
      RAISE EXCEPTION 'Each row needs a product';
    END IF;
    IF v_qty <= 0 THEN
      RAISE EXCEPTION 'Each product needs a quantity greater than 0';
    END IF;
    IF v_rate < 0 THEN
      RAISE EXCEPTION 'Each product needs a rate';
    END IF;
    IF v_gst_percent < 0 THEN
      RAISE EXCEPTION 'GST percent cannot be negative';
    END IF;

    v_taxable := ROUND(v_qty * v_rate, 2);
    v_gst_amount := ROUND(v_taxable * v_gst_percent / 100, 2);
    v_amount := ROUND(v_taxable + v_gst_amount, 2);
    v_subtotal := v_subtotal + v_taxable;
    v_gst_total := v_gst_total + v_gst_amount;
    v_total := v_total + v_amount;
  END LOOP;

  INSERT INTO public.pre_bookings (
    business_id,
    party_id,
    delivery_date,
    notes,
    status,
    subtotal,
    gst_total,
    total_amount
  )
  VALUES (
    trim(p_business_id),
    p_party_id,
    p_delivery_date,
    COALESCE(p_notes, ''),
    'upcoming',
    ROUND(v_subtotal, 2),
    ROUND(v_gst_total, 2),
    ROUND(v_total, 2)
  )
  RETURNING id INTO v_id;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items)
  LOOP
    v_product_id := (v_item ->> 'product_id')::BIGINT;
    v_qty := (v_item ->> 'quantity')::NUMERIC;
    v_rate := COALESCE((v_item ->> 'rate')::NUMERIC, 0);
    IF v_item ->> 'gst_percent' IS NULL OR v_item ->> 'gst_percent' = '' THEN
      v_gst_percent := 18;
    ELSE
      v_gst_percent := COALESCE((v_item ->> 'gst_percent')::NUMERIC, 0);
    END IF;
    v_taxable := ROUND(v_qty * v_rate, 2);
    v_gst_amount := ROUND(v_taxable * v_gst_percent / 100, 2);
    v_amount := ROUND(v_taxable + v_gst_amount, 2);

    INSERT INTO public.pre_booking_items (
      pre_booking_id,
      product_id,
      quantity,
      rate,
      gst_percent,
      gst_amount,
      amount
    )
    VALUES (
      v_id,
      v_product_id,
      v_qty,
      ROUND(v_rate, 2),
      ROUND(v_gst_percent, 2),
      v_gst_amount,
      v_amount
    );
  END LOOP;

  RETURN v_id;
END;
$$;

REVOKE ALL ON FUNCTION public.create_pre_booking(TEXT, BIGINT, DATE, TEXT, JSONB) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.create_pre_booking(TEXT, BIGINT, DATE, TEXT, JSONB)
  TO authenticated, service_role;

DROP FUNCTION IF EXISTS public.update_pre_booking(BIGINT, TEXT, BIGINT, DATE, TEXT, JSONB);

CREATE OR REPLACE FUNCTION public.update_pre_booking(
  p_id BIGINT,
  p_business_id TEXT,
  p_party_id BIGINT,
  p_delivery_date DATE,
  p_notes TEXT,
  p_items JSONB
)
RETURNS BIGINT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_status TEXT;
  v_business_id TEXT;
  v_item JSONB;
  v_product_id BIGINT;
  v_qty NUMERIC(12, 2);
  v_rate NUMERIC(12, 2);
  v_gst_percent NUMERIC(5, 2);
  v_taxable NUMERIC(12, 2);
  v_gst_amount NUMERIC(12, 2);
  v_amount NUMERIC(12, 2);
  v_subtotal NUMERIC(12, 2) := 0;
  v_gst_total NUMERIC(12, 2) := 0;
  v_total NUMERIC(12, 2) := 0;
BEGIN
  IF p_id IS NULL OR p_id <= 0 THEN
    RAISE EXCEPTION 'Pre-booking not found';
  END IF;
  IF p_business_id IS NULL OR length(trim(p_business_id)) = 0 THEN
    RAISE EXCEPTION 'Business is required';
  END IF;
  IF p_party_id IS NULL OR p_party_id <= 0 THEN
    RAISE EXCEPTION 'Party is required';
  END IF;
  IF p_delivery_date IS NULL THEN
    RAISE EXCEPTION 'Delivery date is required';
  END IF;
  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'Add at least one product';
  END IF;

  SELECT status, business_id INTO v_status, v_business_id
  FROM public.pre_bookings
  WHERE id = p_id;

  IF NOT FOUND OR v_business_id IS DISTINCT FROM trim(p_business_id) THEN
    RAISE EXCEPTION 'Pre-booking not found';
  END IF;
  IF v_status IS DISTINCT FROM 'upcoming' THEN
    RAISE EXCEPTION 'Only upcoming pre-bookings can be edited';
  END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items)
  LOOP
    v_product_id := NULLIF(v_item ->> 'product_id', '')::BIGINT;
    v_qty := COALESCE(NULLIF(v_item ->> 'quantity', '')::NUMERIC, 0);
    v_rate := COALESCE(NULLIF(v_item ->> 'rate', '')::NUMERIC, 0);
    IF v_item ->> 'gst_percent' IS NULL OR v_item ->> 'gst_percent' = '' THEN
      v_gst_percent := 18;
    ELSE
      v_gst_percent := COALESCE((v_item ->> 'gst_percent')::NUMERIC, 0);
    END IF;

    IF v_product_id IS NULL OR v_product_id <= 0 THEN
      RAISE EXCEPTION 'Each row needs a product';
    END IF;
    IF v_qty <= 0 THEN
      RAISE EXCEPTION 'Each product needs a quantity greater than 0';
    END IF;
    IF v_rate < 0 THEN
      RAISE EXCEPTION 'Each product needs a rate';
    END IF;
    IF v_gst_percent < 0 THEN
      RAISE EXCEPTION 'GST percent cannot be negative';
    END IF;

    v_taxable := ROUND(v_qty * v_rate, 2);
    v_gst_amount := ROUND(v_taxable * v_gst_percent / 100, 2);
    v_amount := ROUND(v_taxable + v_gst_amount, 2);
    v_subtotal := v_subtotal + v_taxable;
    v_gst_total := v_gst_total + v_gst_amount;
    v_total := v_total + v_amount;
  END LOOP;

  UPDATE public.pre_bookings
  SET
    party_id = p_party_id,
    delivery_date = p_delivery_date,
    notes = COALESCE(p_notes, ''),
    subtotal = ROUND(v_subtotal, 2),
    gst_total = ROUND(v_gst_total, 2),
    total_amount = ROUND(v_total, 2)
  WHERE id = p_id;

  DELETE FROM public.pre_booking_items WHERE pre_booking_id = p_id;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items)
  LOOP
    v_product_id := (v_item ->> 'product_id')::BIGINT;
    v_qty := (v_item ->> 'quantity')::NUMERIC;
    v_rate := COALESCE((v_item ->> 'rate')::NUMERIC, 0);
    IF v_item ->> 'gst_percent' IS NULL OR v_item ->> 'gst_percent' = '' THEN
      v_gst_percent := 18;
    ELSE
      v_gst_percent := COALESCE((v_item ->> 'gst_percent')::NUMERIC, 0);
    END IF;
    v_taxable := ROUND(v_qty * v_rate, 2);
    v_gst_amount := ROUND(v_taxable * v_gst_percent / 100, 2);
    v_amount := ROUND(v_taxable + v_gst_amount, 2);

    INSERT INTO public.pre_booking_items (
      pre_booking_id, product_id, quantity, rate, gst_percent, gst_amount, amount
    )
    VALUES (
      p_id, v_product_id, v_qty, ROUND(v_rate, 2), ROUND(v_gst_percent, 2), v_gst_amount, v_amount
    );
  END LOOP;

  RETURN p_id;
END;
$$;

REVOKE ALL ON FUNCTION public.update_pre_booking(BIGINT, TEXT, BIGINT, DATE, TEXT, JSONB) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.update_pre_booking(BIGINT, TEXT, BIGINT, DATE, TEXT, JSONB)
  TO authenticated, service_role;

