-- ######## supabase.migration.pre_bookings_update.sql ########
-- Additive: atomic update for upcoming pre-bookings.
-- Supabase SQL Editor → Run (safe to re-run). Does not drop tables.

DROP FUNCTION IF EXISTS public.update_pre_booking(BIGINT, TEXT, BIGINT, DATE, TEXT, JSONB);

CREATE OR REPLACE FUNCTION public.update_pre_booking(
  p_id BIGINT,
  p_business_id TEXT,
  p_party_id BIGINT,
  p_delivery_date DATE,
  p_notes TEXT,
  p_items JSONB
)
RETURNS BIGINT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_status TEXT;
  v_business_id TEXT;
  v_item JSONB;
  v_product_id BIGINT;
  v_qty NUMERIC(12, 2);
  v_rate NUMERIC(12, 2);
  v_gst_percent NUMERIC(5, 2);
  v_taxable NUMERIC(12, 2);
  v_gst_amount NUMERIC(12, 2);
  v_amount NUMERIC(12, 2);
  v_subtotal NUMERIC(12, 2) := 0;
  v_gst_total NUMERIC(12, 2) := 0;
  v_total NUMERIC(12, 2) := 0;
BEGIN
  IF p_id IS NULL OR p_id <= 0 THEN
    RAISE EXCEPTION 'Pre-booking not found';
  END IF;
  IF p_business_id IS NULL OR length(trim(p_business_id)) = 0 THEN
    RAISE EXCEPTION 'Business is required';
  END IF;
  IF p_party_id IS NULL OR p_party_id <= 0 THEN
    RAISE EXCEPTION 'Party is required';
  END IF;
  IF p_delivery_date IS NULL THEN
    RAISE EXCEPTION 'Delivery date is required';
  END IF;
  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'Add at least one product';
  END IF;

  SELECT status, business_id INTO v_status, v_business_id
  FROM public.pre_bookings
  WHERE id = p_id;

  IF NOT FOUND OR v_business_id IS DISTINCT FROM trim(p_business_id) THEN
    RAISE EXCEPTION 'Pre-booking not found';
  END IF;
  IF v_status IS DISTINCT FROM 'upcoming' THEN
    RAISE EXCEPTION 'Only upcoming pre-bookings can be edited';
  END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items)
  LOOP
    v_product_id := NULLIF(v_item ->> 'product_id', '')::BIGINT;
    v_qty := COALESCE(NULLIF(v_item ->> 'quantity', '')::NUMERIC, 0);
    v_rate := COALESCE(NULLIF(v_item ->> 'rate', '')::NUMERIC, 0);
    IF v_item ->> 'gst_percent' IS NULL OR v_item ->> 'gst_percent' = '' THEN
      v_gst_percent := 18;
    ELSE
      v_gst_percent := COALESCE((v_item ->> 'gst_percent')::NUMERIC, 0);
    END IF;

    IF v_product_id IS NULL OR v_product_id <= 0 THEN
      RAISE EXCEPTION 'Each row needs a product';
    END IF;
    IF v_qty <= 0 THEN
      RAISE EXCEPTION 'Each product needs a quantity greater than 0';
    END IF;
    IF v_rate < 0 THEN
      RAISE EXCEPTION 'Each product needs a rate';
    END IF;
    IF v_gst_percent < 0 THEN
      RAISE EXCEPTION 'GST percent cannot be negative';
    END IF;

    v_taxable := ROUND(v_qty * v_rate, 2);
    v_gst_amount := ROUND(v_taxable * v_gst_percent / 100, 2);
    v_amount := ROUND(v_taxable + v_gst_amount, 2);
    v_subtotal := v_subtotal + v_taxable;
    v_gst_total := v_gst_total + v_gst_amount;
    v_total := v_total + v_amount;
  END LOOP;

  UPDATE public.pre_bookings
  SET
    party_id = p_party_id,
    delivery_date = p_delivery_date,
    notes = COALESCE(p_notes, ''),
    subtotal = ROUND(v_subtotal, 2),
    gst_total = ROUND(v_gst_total, 2),
    total_amount = ROUND(v_total, 2)
  WHERE id = p_id;

  DELETE FROM public.pre_booking_items WHERE pre_booking_id = p_id;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items)
  LOOP
    v_product_id := (v_item ->> 'product_id')::BIGINT;
    v_qty := (v_item ->> 'quantity')::NUMERIC;
    v_rate := COALESCE((v_item ->> 'rate')::NUMERIC, 0);
    IF v_item ->> 'gst_percent' IS NULL OR v_item ->> 'gst_percent' = '' THEN
      v_gst_percent := 18;
    ELSE
      v_gst_percent := COALESCE((v_item ->> 'gst_percent')::NUMERIC, 0);
    END IF;
    v_taxable := ROUND(v_qty * v_rate, 2);
    v_gst_amount := ROUND(v_taxable * v_gst_percent / 100, 2);
    v_amount := ROUND(v_taxable + v_gst_amount, 2);

    INSERT INTO public.pre_booking_items (
      pre_booking_id,
      product_id,
      quantity,
      rate,
      gst_percent,
      gst_amount,
      amount
    )
    VALUES (
      p_id,
      v_product_id,
      v_qty,
      ROUND(v_rate, 2),
      ROUND(v_gst_percent, 2),
      v_gst_amount,
      v_amount
    );
  END LOOP;

  RETURN p_id;
END;
$$;

REVOKE ALL ON FUNCTION public.update_pre_booking(BIGINT, TEXT, BIGINT, DATE, TEXT, JSONB) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.update_pre_booking(BIGINT, TEXT, BIGINT, DATE, TEXT, JSONB)
  TO authenticated, service_role;



-- ######## supabase.migration.offers.sql ########
-- =============================================
-- Offers as fixed combo packages + pre_bookings.offer_id
-- Run in Supabase SQL Editor. Safe to re-run.
-- =============================================

CREATE TABLE IF NOT EXISTS public.offers (
  id BIGSERIAL PRIMARY KEY,
  business_id TEXT NOT NULL,
  offer_name TEXT NOT NULL,
  combo_price NUMERIC(12, 2) NOT NULL DEFAULT 0 CHECK (combo_price >= 0),
  valid_from DATE,
  valid_to DATE,
  is_active BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

COMMENT ON TABLE public.offers IS
  'Fixed combo packages (e.g. ₹349 Combo). combo_price is the final amount the customer pays for the whole set.';
COMMENT ON COLUMN public.offers.combo_price IS
  'Final fixed price for the entire combo, not a per-product discount.';

CREATE INDEX IF NOT EXISTS offers_business_id_idx ON public.offers (business_id);
CREATE INDEX IF NOT EXISTS offers_is_active_idx ON public.offers (is_active);
CREATE INDEX IF NOT EXISTS offers_valid_from_idx ON public.offers (valid_from);
CREATE INDEX IF NOT EXISTS offers_valid_to_idx ON public.offers (valid_to);

ALTER TABLE public.offers ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS offers_authenticated_all ON public.offers;
CREATE POLICY offers_authenticated_all
  ON public.offers
  FOR ALL 
  TO authenticated
  USING (true)
  WITH CHECK (true);

GRANT SELECT, INSERT, UPDATE, DELETE ON public.offers TO authenticated;
GRANT ALL ON public.offers TO service_role;
GRANT USAGE, SELECT ON SEQUENCE public.offers_id_seq TO authenticated;
GRANT ALL ON SEQUENCE public.offers_id_seq TO service_role;

CREATE TABLE IF NOT EXISTS public.offer_items (
  id BIGSERIAL PRIMARY KEY,
  offer_id BIGINT NOT NULL REFERENCES public.offers (id) ON DELETE CASCADE,
  product_id BIGINT NOT NULL REFERENCES public.products (id) ON DELETE RESTRICT,
  quantity NUMERIC(12, 2) NOT NULL CHECK (quantity > 0),
  rate NUMERIC(12, 2) NOT NULL DEFAULT 0 CHECK (rate >= 0),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

COMMENT ON TABLE public.offer_items IS
  'Fixed products, quantities, and combo-specific retail rates included in a combo offer.';
COMMENT ON COLUMN public.offer_items.rate IS
  'Retail unit rate for this product inside this combo. May differ from products.retail_price.';

CREATE INDEX IF NOT EXISTS offer_items_offer_idx ON public.offer_items (offer_id);
CREATE INDEX IF NOT EXISTS offer_items_product_idx ON public.offer_items (product_id);

ALTER TABLE public.offer_items ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS offer_items_authenticated_all ON public.offer_items;
CREATE POLICY offer_items_authenticated_all
  ON public.offer_items
  FOR ALL
  TO authenticated
  USING (true)
  WITH CHECK (true);

GRANT SELECT, INSERT, UPDATE, DELETE ON public.offer_items TO authenticated;
GRANT ALL ON public.offer_items TO service_role;
GRANT USAGE, SELECT ON SEQUENCE public.offer_items_id_seq TO authenticated;
GRANT ALL ON SEQUENCE public.offer_items_id_seq TO service_role;

ALTER TABLE public.offer_items
  ADD COLUMN IF NOT EXISTS rate NUMERIC(12, 2) NOT NULL DEFAULT 0 CHECK (rate >= 0);

ALTER TABLE public.pre_bookings
  ADD COLUMN IF NOT EXISTS offer_id BIGINT REFERENCES public.offers (id) ON DELETE SET NULL;

CREATE INDEX IF NOT EXISTS pre_bookings_offer_id_idx ON public.pre_bookings (offer_id);

COMMENT ON COLUMN public.pre_bookings.offer_id IS
  'Optional combo offer used when this pre-booking was created. Null = manual line items.';

DO $$
BEGIN
  ALTER PUBLICATION supabase_realtime ADD TABLE public.offers;
EXCEPTION
  WHEN duplicate_object THEN NULL;
  WHEN undefined_object THEN
    RAISE NOTICE 'Realtime publication not found — skip offers';
END $$;

DO $$
BEGIN
  ALTER PUBLICATION supabase_realtime ADD TABLE public.offer_items;
EXCEPTION
  WHEN duplicate_object THEN NULL;
  WHEN undefined_object THEN
    RAISE NOTICE 'Realtime publication not found — skip offer_items';
END $$;



