-- ######## supabase.migration.delete_business_cascade.sql ########
-- Permanently delete a business and every row that belongs to it.
-- Run once in Supabase → SQL Editor → Run (safe to re-run).
--
-- Inspect live FKs (optional):
--   SELECT conrelid::regclass AS from_table, a.attname AS from_col, confrelid::regclass AS to_table
--   FROM pg_constraint c
--   JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = ANY (c.conkey)
--   WHERE c.contype = 'f' AND confrelid IN ('public.businesses'::regclass, 'public.user_profiles'::regclass);

CREATE OR REPLACE FUNCTION public._rel_exists(p_table TEXT)
RETURNS BOOLEAN
LANGUAGE sql
STABLE
AS $$
  SELECT to_regclass('public.' || p_table) IS NOT NULL;
$$;

CREATE OR REPLACE FUNCTION public._col_exists(p_table TEXT, p_column TEXT)
RETURNS BOOLEAN
LANGUAGE sql
STABLE
AS $$
  SELECT EXISTS (
    SELECT 1
    FROM information_schema.columns
    WHERE table_schema = 'public'
      AND table_name = p_table
      AND column_name = p_column
  );
$$;

CREATE OR REPLACE FUNCTION public.delete_business_cascade(p_business_id TEXT)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_business RECORD;
  v_profile_ids UUID[] := '{}';
  v_owner_emails TEXT[] := '{}';
  v_fk RECORD;
  v_table TEXT;
  v_deleted JSONB := '{}'::jsonb;
  v_count BIGINT;
BEGIN
  IF p_business_id IS NULL OR btrim(p_business_id) = '' THEN
    RAISE EXCEPTION 'Business id is required';
  END IF;

  EXECUTE
    'SELECT id::text AS id, business_name, owner_email FROM public.businesses WHERE id::text = $1 LIMIT 1'
    INTO v_business
    USING p_business_id;

  IF v_business.id IS NULL THEN
    RAISE EXCEPTION 'Business not found';
  END IF;

  IF public._col_exists('user_profiles', 'business_id') THEN
    EXECUTE
      'SELECT COALESCE(array_agg(id), ''{}'') FROM public.user_profiles WHERE business_id::text = $1'
      INTO v_profile_ids
      USING p_business_id;
  END IF;

  IF v_business.owner_email IS NOT NULL AND public._col_exists('user_profiles', 'email') THEN
    EXECUTE
      $q$
        SELECT COALESCE(array_agg(DISTINCT id), '{}')
        FROM public.user_profiles
        WHERE lower(email) = lower($1)
           OR id = ANY($2)
      $q$
      INTO v_profile_ids
      USING v_business.owner_email, v_profile_ids;
  END IF;

  SELECT COALESCE(array_agg(email), '{}')
  INTO v_owner_emails
  FROM public.user_profiles
  WHERE id = ANY (v_profile_ids);

  -- Break leftover FKs to these profiles (e.g. sales.deleted_by).
  FOR v_fk IN
    SELECT
      c.relname AS table_name,
      a.attname AS column_name,
      conf.confdeltype
    FROM pg_constraint conf
    JOIN pg_class c ON c.oid = conf.conrelid
    JOIN pg_namespace n ON n.oid = c.relnamespace
    JOIN pg_attribute a ON a.attrelid = conf.conrelid AND a.attnum = ANY (conf.conkey)
    JOIN pg_class ref ON ref.oid = conf.confrelid
    JOIN pg_namespace rn ON rn.oid = ref.relnamespace
    WHERE conf.contype = 'f'
      AND n.nspname = 'public'
      AND rn.nspname = 'public'
      AND ref.relname = 'user_profiles'
      AND conf.confdeltype IN ('a', 'r') -- NO ACTION / RESTRICT
  LOOP
    IF cardinality(v_profile_ids) = 0 THEN
      EXIT;
    END IF;
    EXECUTE format(
      'UPDATE public.%I SET %I = NULL WHERE %I = ANY ($1)',
      v_fk.table_name,
      v_fk.column_name,
      v_fk.column_name
    )
    USING v_profile_ids;
  END LOOP;

  -- Child rows of employees / sales / purchases before those parents.
  IF public._rel_exists('salary_payments') AND public._rel_exists('employees') AND public._col_exists('employees', 'business_id') THEN
    EXECUTE
      'DELETE FROM public.salary_payments WHERE employee_id IN (SELECT id FROM public.employees WHERE business_id::text = $1)'
      USING p_business_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_deleted := v_deleted || jsonb_build_object('salary_payments', v_count);
  END IF;

  IF public._rel_exists('sale_items') AND public._rel_exists('sales') THEN
    IF public._col_exists('sales', 'business_id') THEN
      EXECUTE
        'DELETE FROM public.sale_items WHERE sale_id IN (SELECT id FROM public.sales WHERE business_id::text = $1)'
        USING p_business_id;
    ELSIF public._col_exists('parties', 'business_id') THEN
      EXECUTE
        'DELETE FROM public.sale_items WHERE sale_id IN (
           SELECT s.id FROM public.sales s
           JOIN public.parties p ON p.id = s.party_id
           WHERE p.business_id::text = $1
         )'
        USING p_business_id;
    END IF;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_deleted := v_deleted || jsonb_build_object('sale_items', v_count);
  END IF;

  IF public._rel_exists('purchase_items') AND public._rel_exists('purchases') THEN
    IF public._col_exists('purchases', 'business_id') THEN
      EXECUTE
        'DELETE FROM public.purchase_items WHERE purchase_id IN (SELECT id FROM public.purchases WHERE business_id::text = $1)'
        USING p_business_id;
    ELSIF public._col_exists('parties', 'business_id') THEN
      EXECUTE
        'DELETE FROM public.purchase_items WHERE purchase_id IN (
           SELECT pu.id FROM public.purchases pu
           JOIN public.parties p ON p.id = pu.party_id
           WHERE p.business_id::text = $1
         )'
        USING p_business_id;
    END IF;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_deleted := v_deleted || jsonb_build_object('purchase_items', v_count);
  END IF;

  -- Known operational tables that may have business_id in the live DB.
  FOREACH v_table IN ARRAY ARRAY[
    'sales',
    'purchases',
    'expenses',
    'employees',
    'products',
    'parties',
    'activity_log',
    'business_settings'
  ]
  LOOP
    IF public._rel_exists(v_table) AND public._col_exists(v_table, 'business_id') THEN
      EXECUTE format('DELETE FROM public.%I WHERE business_id::text = $1', v_table)
      USING p_business_id;
      GET DIAGNOSTICS v_count = ROW_COUNT;
      v_deleted := v_deleted || jsonb_build_object(v_table, v_count);
    ELSIF v_table IN ('sales', 'purchases')
      AND public._rel_exists(v_table)
      AND public._rel_exists('parties')
      AND public._col_exists('parties', 'business_id')
      AND public._col_exists(v_table, 'party_id')
    THEN
      EXECUTE format(
        'DELETE FROM public.%I WHERE party_id IN (SELECT id FROM public.parties WHERE business_id::text = $1)',
        v_table
      )
      USING p_business_id;
      GET DIAGNOSTICS v_count = ROW_COUNT;
      v_deleted := v_deleted || jsonb_build_object(v_table, v_count);
    END IF;
  END LOOP;

  -- Any other table that FKs to businesses (covers employees_business_id_fkey and future tables).
  FOR v_fk IN
    SELECT
      c.relname AS table_name,
      a.attname AS column_name,
      conf.confdeltype
    FROM pg_constraint conf
    JOIN pg_class c ON c.oid = conf.conrelid
    JOIN pg_namespace n ON n.oid = c.relnamespace
    JOIN pg_attribute a ON a.attrelid = conf.conrelid AND a.attnum = ANY (conf.conkey)
    JOIN pg_class ref ON ref.oid = conf.confrelid
    JOIN pg_namespace rn ON rn.oid = ref.relnamespace
    WHERE conf.contype = 'f'
      AND n.nspname = 'public'
      AND rn.nspname = 'public'
      AND ref.relname = 'businesses'
      AND c.relname <> 'user_profiles'
  LOOP
    IF v_fk.confdeltype = 'n' THEN
      EXECUTE format(
        'UPDATE public.%I SET %I = NULL WHERE %I::text = $1',
        v_fk.table_name,
        v_fk.column_name,
        v_fk.column_name
      )
      USING p_business_id;
    ELSE
      EXECUTE format(
        'DELETE FROM public.%I WHERE %I::text = $1',
        v_fk.table_name,
        v_fk.column_name
      )
      USING p_business_id;
    END IF;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_deleted := v_deleted || jsonb_build_object(v_fk.table_name, v_count);
  END LOOP;

  -- Remaining public tables with a business_id column (no FK, or added later).
  FOR v_table IN
    SELECT table_name
    FROM information_schema.columns
    WHERE table_schema = 'public'
      AND column_name = 'business_id'
      AND table_name NOT IN ('businesses', 'user_profiles')
  LOOP
    EXECUTE format('DELETE FROM public.%I WHERE business_id::text = $1', v_table)
    USING p_business_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_deleted := v_deleted || jsonb_build_object(v_table, v_count);
  END LOOP;

  IF public._rel_exists('support_messages') AND cardinality(v_profile_ids) > 0 THEN
    DELETE FROM public.support_messages WHERE user_id = ANY (v_profile_ids);
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_deleted := v_deleted || jsonb_build_object('support_messages', v_count);
  END IF;

  IF public._rel_exists('user_dashboard_preferences') AND cardinality(v_profile_ids) > 0 THEN
    DELETE FROM public.user_dashboard_preferences WHERE user_id = ANY (v_profile_ids);
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_deleted := v_deleted || jsonb_build_object('user_dashboard_preferences', v_count);
  END IF;

  IF cardinality(v_profile_ids) > 0 THEN
    DELETE FROM public.user_profiles WHERE id = ANY (v_profile_ids);
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_deleted := v_deleted || jsonb_build_object('user_profiles', v_count);
  END IF;

  EXECUTE 'DELETE FROM public.businesses WHERE id::text = $1' USING p_business_id;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  IF v_count = 0 THEN
    RAISE EXCEPTION 'Business could not be deleted';
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'business_id', v_business.id,
    'business_name', v_business.business_name,
    'profile_ids', to_jsonb(v_profile_ids),
    'owner_emails', to_jsonb(v_owner_emails),
    'deleted', v_deleted
  );
END;
$$;

REVOKE ALL ON FUNCTION public.delete_business_cascade(TEXT) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.delete_business_cascade(TEXT) TO service_role;



-- ######## supabase.migration.invoices_storage.sql ########
-- =============================================
-- Invoice PDFs for WhatsApp share
-- Bucket: invoices (public read)
-- Run in Supabase SQL Editor if the API cannot create the bucket.
-- =============================================

INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
VALUES (
  'invoices',
  'invoices',
  true,
  10485760,
  ARRAY['application/pdf']::text[]
)
ON CONFLICT (id) DO UPDATE
SET
  public = EXCLUDED.public,
  file_size_limit = EXCLUDED.file_size_limit,
  allowed_mime_types = EXCLUDED.allowed_mime_types;

-- Public read for WhatsApp / clients
DROP POLICY IF EXISTS "invoices_public_read" ON storage.objects;
CREATE POLICY "invoices_public_read"
  ON storage.objects
  FOR SELECT
  TO public
  USING (bucket_id = 'invoices');

-- Authenticated / service uploads (service role bypasses RLS; this helps client uploads if ever used)
DROP POLICY IF EXISTS "invoices_authenticated_insert" ON storage.objects;
CREATE POLICY "invoices_authenticated_insert"
  ON storage.objects
  FOR INSERT
  TO authenticated
  WITH CHECK (bucket_id = 'invoices');

DROP POLICY IF EXISTS "invoices_authenticated_update" ON storage.objects;
CREATE POLICY "invoices_authenticated_update"
  ON storage.objects
  FOR UPDATE
  TO authenticated
  USING (bucket_id = 'invoices')
  WITH CHECK (bucket_id = 'invoices');


-- ######## supabase.migration.realtime.sql ########
-- Enable Supabase Realtime for app tables (run once in Supabase SQL Editor).
-- Required for automatic UI updates when rows change in Supabase dashboard.

DO $$
DECLARE
  tbl text;
BEGIN
  FOR tbl IN
    SELECT unnest(ARRAY[
      'parties',
      'products',
      'sales',
      'sale_items',
      'purchases',
      'purchase_items',
      'expenses',
      'employees',
      'user_profiles'
    ])
  LOOP
    BEGIN
      EXECUTE format(
        'ALTER PUBLICATION supabase_realtime ADD TABLE public.%I',
        tbl
      );
    EXCEPTION
      WHEN duplicate_object THEN
        NULL;
      WHEN undefined_object THEN
        RAISE NOTICE 'Table % not found — skip', tbl;
    END;
  END LOOP;
END $$;


-- ######## setup/99_multi_business.sql ########
-- =============================================
-- 99 — One database, many businesses: business_id on every table + row security
-- Runs LAST in supabase.full-setup.sql.
--
-- * Every business table gets business_id, filled in automatically from the signed-in
--   user's profile (public.current_business_id()), so the API and the RPC functions
--   never have to pass it.
-- * Row Level Security only shows a business its own rows. The backend's service-role
--   key (used for admin tasks) bypasses this, as before.
-- =============================================

-- Old 5-argument versions are superseded by the 6-argument ones (with p_payment).
DROP FUNCTION IF EXISTS public.create_sale(BIGINT, TEXT, DATE, NUMERIC, JSONB);
DROP FUNCTION IF EXISTS public.update_sale(BIGINT, BIGINT, DATE, NUMERIC, JSONB);

-- business_settings: the old file made a single-row table (id = 1); the app keeps one row
-- per business and upserts ON CONFLICT (business_id).
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'business_settings' AND column_name = 'business_id'
  ) THEN
    ALTER TABLE public.business_settings DROP CONSTRAINT IF EXISTS business_settings_id_check;
    ALTER TABLE public.business_settings ALTER COLUMN id DROP DEFAULT;
    ALTER TABLE public.business_settings ALTER COLUMN id TYPE BIGINT;
    CREATE SEQUENCE IF NOT EXISTS public.business_settings_id_seq OWNED BY public.business_settings.id;
    PERFORM setval('public.business_settings_id_seq', GREATEST((SELECT MAX(id) FROM public.business_settings), 1));
    ALTER TABLE public.business_settings
      ALTER COLUMN id SET DEFAULT nextval('public.business_settings_id_seq');
    ALTER TABLE public.business_settings ADD COLUMN business_id UUID;
  END IF;
END $$;

ALTER TABLE public.business_settings ADD COLUMN IF NOT EXISTS signature_url TEXT NOT NULL DEFAULT '';
ALTER TABLE public.business_settings ADD COLUMN IF NOT EXISTS stamp_url TEXT NOT NULL DEFAULT '';
GRANT USAGE, SELECT ON SEQUENCE public.business_settings_id_seq TO authenticated, service_role;

-- Activity log: allow every action/entity the app records (employees, offers, cities, ...).
ALTER TABLE public.activity_log DROP CONSTRAINT IF EXISTS activity_log_action_type_check;
ALTER TABLE public.activity_log DROP CONSTRAINT IF EXISTS activity_log_entity_type_check;
ALTER TABLE public.activity_log ADD CONSTRAINT activity_log_action_type_check CHECK (
  action_type IN ('create', 'update', 'delete', 'mark_paid', 'mark_salary_paid',
                  'cancel', 'deactivate', 'reactivate')
);
ALTER TABLE public.activity_log ADD CONSTRAINT activity_log_entity_type_check CHECK (
  entity_type IN ('product', 'party', 'purchase', 'sale', 'expense', 'settings', 'employee',
                  'offer', 'pre_booking', 'business_city')
);

-- UUID business_id + default + FK on every business table.
DO $$
DECLARE
  t TEXT;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'products', 'parties', 'purchases', 'purchase_items', 'sales', 'sale_items',
    'expenses', 'employees', 'salary_payments', 'activity_log', 'business_settings'
  ]
  LOOP
    EXECUTE format('ALTER TABLE public.%I ADD COLUMN IF NOT EXISTS business_id UUID', t);
    EXECUTE format(
      'ALTER TABLE public.%I ALTER COLUMN business_id SET DEFAULT public.current_business_id()', t);
    EXECUTE format('ALTER TABLE public.%I DROP CONSTRAINT IF EXISTS %I', t, t || '_business_id_fkey');
    EXECUTE format(
      'ALTER TABLE public.%I ADD CONSTRAINT %I FOREIGN KEY (business_id) REFERENCES public.businesses (id) ON DELETE CASCADE',
      t, t || '_business_id_fkey');
    EXECUTE format('CREATE INDEX IF NOT EXISTS %I ON public.%I (business_id)', t || '_business_id_idx', t);
  END LOOP;
END $$;

CREATE UNIQUE INDEX IF NOT EXISTS business_settings_business_id_key
  ON public.business_settings (business_id);

-- Tables created with a TEXT business_id (cities, offers, pre-bookings): default only.
DO $$
DECLARE
  t TEXT;
BEGIN
  FOREACH t IN ARRAY ARRAY['business_cities', 'offers', 'offer_items', 'pre_bookings', 'pre_booking_items']
  LOOP
    IF EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = t AND column_name = 'business_id'
    ) THEN
      EXECUTE format(
        'ALTER TABLE public.%I ALTER COLUMN business_id SET DEFAULT public.current_business_id()::text', t);
    END IF;
  END LOOP;
END $$;

-- Row Level Security: replace the open "USING (true)" policies with per-business ones.
DO $$
DECLARE
  t TEXT;
  pol RECORD;
  cond TEXT;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'products', 'parties', 'purchases', 'purchase_items', 'sales', 'sale_items',
    'expenses', 'employees', 'salary_payments', 'activity_log', 'business_settings',
    'business_cities', 'offers', 'offer_items', 'pre_bookings', 'pre_booking_items'
  ]
  LOOP
    IF to_regclass('public.' || t) IS NULL THEN
      CONTINUE;
    END IF;

    IF EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = t AND column_name = 'business_id'
        AND data_type = 'uuid'
    ) THEN
      cond := 'business_id = public.current_business_id()';
    ELSIF EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = t AND column_name = 'business_id'
    ) THEN
      cond := 'business_id = public.current_business_id()::text';
    ELSE
      CONTINUE;  -- no business_id column: leave this table's policies alone
    END IF;

    FOR pol IN SELECT policyname FROM pg_policies WHERE schemaname = 'public' AND tablename = t
    LOOP
      EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', pol.policyname, t);
    END LOOP;

    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY %I ON public.%I FOR ALL TO authenticated USING (%s) WITH CHECK (%s)',
      t || '_own_business', t, cond, cond);
    EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON public.%I TO authenticated', t);
    EXECUTE format('GRANT ALL ON public.%I TO service_role', t);
    -- Signed-out (anon) requests get nothing.
    EXECUTE format('REVOKE ALL ON public.%I FROM anon', t);
  END LOOP;
END $$;

-- Line tables without their own business_id follow their parent row.
DROP POLICY IF EXISTS offer_items_authenticated_all ON public.offer_items;
DROP POLICY IF EXISTS offer_items_own_business ON public.offer_items;
CREATE POLICY offer_items_own_business ON public.offer_items
  FOR ALL TO authenticated
  USING (EXISTS (
    SELECT 1 FROM public.offers o
    WHERE o.id = offer_id AND o.business_id = public.current_business_id()::text))
  WITH CHECK (EXISTS (
    SELECT 1 FROM public.offers o
    WHERE o.id = offer_id AND o.business_id = public.current_business_id()::text));
REVOKE ALL ON public.offer_items FROM anon;

DROP POLICY IF EXISTS pre_booking_items_authenticated_all ON public.pre_booking_items;
DROP POLICY IF EXISTS pre_booking_items_own_business ON public.pre_booking_items;
CREATE POLICY pre_booking_items_own_business ON public.pre_booking_items
  FOR ALL TO authenticated
  USING (EXISTS (
    SELECT 1 FROM public.pre_bookings b
    WHERE b.id = pre_booking_id AND b.business_id = public.current_business_id()::text))
  WITH CHECK (EXISTS (
    SELECT 1 FROM public.pre_bookings b
    WHERE b.id = pre_booking_id AND b.business_id = public.current_business_id()::text));
REVOKE ALL ON public.pre_booking_items FROM anon;

-- business_cities seeds a city for the OLD live database's business id; drop rows
-- that don't belong to any business in this database.
DELETE FROM public.business_cities
WHERE business_id NOT IN (SELECT id::text FROM public.businesses);

-- Teammates in the same business can see each other's profile (own row always visible).
DROP POLICY IF EXISTS user_profiles_select_same_business ON public.user_profiles;
CREATE POLICY user_profiles_select_same_business ON public.user_profiles
  FOR SELECT TO authenticated
  USING (business_id IS NOT NULL AND business_id = public.current_business_id());
REVOKE ALL ON public.user_profiles FROM anon;

GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO authenticated, service_role;

-- Storage bucket for logo / signature / stamp uploads (Business settings page).
INSERT INTO storage.buckets (id, name, public)
VALUES ('business-assets', 'business-assets', true)
ON CONFLICT (id) DO UPDATE SET public = EXCLUDED.public;

DROP POLICY IF EXISTS "business_assets_public_read" ON storage.objects;
CREATE POLICY "business_assets_public_read"
  ON storage.objects FOR SELECT TO public
  USING (bucket_id = 'business-assets');

-- =============================================
-- First owner login (email + password)
-- 1. Supabase -> Authentication -> Users -> Add user (tick "Auto Confirm User").
-- 2. Run once, with that email:
--      SELECT public.setup_business_owner('you@example.com', 'Aura Cleans', 'Your Name');
-- (Signing up from the app's own Sign-up page also creates the business + owner.)
-- =============================================
CREATE OR REPLACE FUNCTION public.setup_business_owner(
  p_email TEXT,
  p_business_name TEXT DEFAULT 'Aura Cleans',
  p_full_name TEXT DEFAULT 'Owner'
)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_user_id UUID;
  v_business_id UUID;
BEGIN
  SELECT id INTO v_user_id FROM auth.users WHERE lower(email) = lower(btrim(p_email)) LIMIT 1;
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'No login found for %. Create it first in Authentication -> Users.', p_email;
  END IF;

  SELECT business_id INTO v_business_id FROM public.user_profiles WHERE id = v_user_id;
  IF v_business_id IS NULL THEN
    INSERT INTO public.businesses (business_name, owner_email, status, payment_status)
    VALUES (p_business_name, lower(btrim(p_email)), 'active', 'paid')
    RETURNING id INTO v_business_id;
  END IF;

  INSERT INTO public.user_profiles (id, full_name, email, role, business_id)
  VALUES (v_user_id, p_full_name, lower(btrim(p_email)), 'admin', v_business_id)
  ON CONFLICT (id) DO UPDATE
    SET role = 'admin', business_id = EXCLUDED.business_id;

  INSERT INTO public.business_settings (business_id, company_name)
  VALUES (v_business_id, p_business_name)
  ON CONFLICT (business_id) DO NOTHING;

  RETURN v_business_id;
END;
$$;

REVOKE ALL ON FUNCTION public.setup_business_owner(TEXT, TEXT, TEXT) FROM PUBLIC, anon, authenticated;


NOTIFY pgrst, 'reload schema';
